#include <vector>
#include <complex>
#include <algorithm>
#include <omp.h>

/* Sort the vector x of complex numbers by their magnitude in ascending order.
   Use OpenMP to sort in parallel.
   Example:

   input: [3.0-1.0i, 4.5+2.1i, 0.0-1.0i, 1.0-0.0i, 0.5+0.5i]
   output: [0.5+0.5i, 0.0-1.0i, 1.0-0.0i, 3.0-1.0i, 4.5+2.1i]
*/
void sortComplexByMagnitude(std::vector<std::complex<double>> &x) {
    const std::size_t n = x.size();
    if (n < 2) return;

    // Parallel odd-even transposition sort (stable for strict ">" comparisons).
    // Correct under any thread count; each compared pair is disjoint per phase.
    for (std::size_t phase = 0; phase < n; ++phase) {
        const std::size_t start = phase % 2; // even phase: (0,1),(2,3)...; odd: (1,2),(3,4)...
        const std::size_t pairCount = (n > start + 1) ? ((n - start - 1) / 2) : 0;

        #pragma omp parallel for schedule(static)
        for (std::ptrdiff_t k = 0; k < static_cast<std::ptrdiff_t>(pairCount); ++k) {
            const std::size_t i = start + 2 * static_cast<std::size_t>(k);
            const std::size_t j = i + 1;

            // Compare by magnitude squared to avoid sqrt.
            const double mi = std::norm(x[i]);
            const double mj = std::norm(x[j]);

            if (mi > mj) {
                std::swap(x[i], x[j]);
            }
        }
        // Implicit barrier at end of omp for ensures phase completion.
    }
}
